#include <stdio.h>

/* teste do desafio pares-e-regressivos — counter_protocol (03-tdd 3.9.3).
   O main e o relatorio sao do harness; aqui so existem cenarios SM_TEST.
   Cada cenario escreve num arquivo o N que a pessoa "digitaria", aponta o
   stdin para esse arquivo (freopen), captura o stdout no proprio teste e le
   as linhas de volta. Os nomes dos arquivos temporarios sao POR CENARIO: um
   cenario nunca le a entrada nem a captura do outro. Nunca ha fclose de
   stdin/stdout — so fflush — para o segundo freopen ficar legal (C11 7.21.4).
   Os dois N sao diferentes de proposito: uma lista escrita a mao reprova. */

/* prototipo da funcao do aluno (o teste declara o que exercita) */
void paresERegressivos(void);

SM_TEST(as_duas_listas_de_dez) {
    /* o que a pessoa digita: o N desta rodada */
    FILE *e = fopen("sm_entrada_1.tmp", "w");
    fprintf(e, "10\n");
    fclose(e);
    freopen("sm_entrada_1.tmp", "r", stdin);

    /* captura: o stdout vira o arquivo sm_saida_1.tmp */
    freopen("sm_saida_1.tmp", "w", stdout);
    paresERegressivos();
