#include <stdio.h>

void paresERegressivos(void) {
    int n = 0;

    scanf("%d", &n);

    printf("pares\n");
    for (int i = 2; i <= n; i += 2) {
        printf("%d\n", i);
    }

    printf("regressivos\n");
    for (int m = n; m >= 5; m -= 5) {
        printf("%d\n", m);
    }
}
